arguments.file_text:
@page "/apply"
@rendermode InteractiveServer
@using sv_a81bc722eab54535b4185d6e3fc46a91.Models
@using sv_a81bc722eab54535b4185d6e3fc46a91.Services
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<h1 class="mb-4">Job Application</h1>

@if (Submitted)
{
    <div class="alert alert-success text-center py-5">
        <h2>🎉 Application Submitted!</h2>
        <p class="lead mt-3">Your application has been received.</p>
        <p>Application ID: <strong>@ApplicationId</strong></p>
    </div>
}
else
{
    <StepIndicator CurrentStep="CurrentStep"
                   CompletedSteps="CompletedSteps"
                   OnStepClicked="GoToStep" />

    <div class="card mt-4">
        <div class="card-body">
            @if (CurrentStep == 1)
            {
                <StepPersonalInfo FullName="@FullName"
                                  Email="@Email"
                                  Phone="@Phone"
                                  Address="@Address"
                                  FullNameChanged="v => FullName = v"
                                  EmailChanged="v => Email = v"
                                  PhoneChanged="v => Phone = v"
                                  AddressChanged="v => Address = v"
                                  EmailError="@EmailError"
                                  ValidationErrors="@ValidationErrors"
                                  OnNext="NextFromPersonalInfo" />
            }
            else if (CurrentStep == 2)
            {
                <StepWorkHistory WorkEntries="WorkEntries"
                                 CurrentFlags="CurrentJobFlags"
                                 ValidationErrors="@ValidationErrors"
                                 OnBack="Back"
                                 OnNext="NextFromWorkHistory" />
            }
            else if (CurrentStep == 3)
            {
                <StepReferences References="References"
                                ValidationErrors="@ValidationErrors"
                                OnBack="Back"
                                OnNext="NextFromReferences" />
            }
            else if (CurrentStep == 4)
            {
                <StepCoverLetter CoverLetter="@CoverLetter"
                                 CoverLetterChanged="v => CoverLetter = v"
                                 OnBack="Back"
                                 OnNext="NextFromCoverLetter" />
            }
            else if (CurrentStep == 5)
            {
                <StepReview FullName="@FullName"
                            Email="@Email"
                            Phone="@Phone"
                            Address="@Address"
                            WorkEntries="WorkEntries"
                            CurrentFlags="CurrentJobFlags"
                            References="References"
                            CoverLetter="@CoverLetter"
                            IsSubmitting="IsSubmitting"
                            OnEdit="GoToStep"
                            OnSubmit="SubmitApplication" />
            }
        </div>
    </div>
}

@code {
    private int CurrentStep { get; set; } = 1;
    private HashSet<int> CompletedSteps { get; set; } = new();
    private List<string> ValidationErrors { get; set; } = new();
    private string? EmailError { get; set; }
    private bool IsSubmitting { get; set; }
    private bool Submitted { get; set; }
    private int ApplicationId { get; set; }

    // Step 1
    private string FullName { get; set; } = "";
    private string Email { get; set; } = "";
    private string Phone { get; set; } = "";
    private string Address { get; set; } = "";

    // Step 2
    private List<WorkEntryModel> WorkEntries { get; set; } = new() { new WorkEntryModel() };
    private List<bool> CurrentJobFlags { get; set; } = new() { false };

    // Step 3
    private List<ReferenceModel> References { get; set; } = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4
    private string CoverLetter { get; set; } = "";

    private void GoToStep(int step)
    {
        if (CompletedSteps.Contains(step) || step == CurrentStep)
        {
            ValidationErrors.Clear();
            EmailError = null;
            CurrentStep = step;
        }
    }

    private void Back()
    {
        ValidationErrors.Clear();
        EmailError = null;
        CurrentStep--;
    }

    private async Task NextFromPersonalInfo()
    {
        ValidationErrors.Clear();
        EmailError = null;

        if (string.IsNullOrWhiteSpace(FullName))
            ValidationErrors.Add("Full name is required.");
        if (string.IsNullOrWhiteSpace(Email))
            ValidationErrors.Add("Email is required.");
        if (string.IsNullOrWhiteSpace(Phone))
            ValidationErrors.Add("Phone is required.");
        if (string.IsNullOrWhiteSpace(Address))
            ValidationErrors.Add("Address is required.");

        if (ValidationErrors.Count > 0) return;

        var emailValid = await ApplicationService.ValidateEmailAsync(Email);
        if (!emailValid)
        {
            EmailError = "Please enter a valid email address.";
            return;
        }

        CompletedSteps.Add(1);
        CurrentStep = 2;
    }

    private void NextFromWorkHistory()
    {
        ValidationErrors.Clear();

        for (int i = 0; i < WorkEntries.Count; i++)
        {
            var e = WorkEntries[i];
            if (string.IsNullOrWhiteSpace(e.Company))
                ValidationErrors.Add($"Entry {i + 1}: Company name is required.");
            if (string.IsNullOrWhiteSpace(e.Title))
                ValidationErrors.Add($"Entry {i + 1}: Job title is required.");
            if (e.StartDate == default)
                ValidationErrors.Add($"Entry {i + 1}: Start date is required.");
        }

        if (ValidationErrors.Count > 0) return;

        CompletedSteps.Add(2);
        CurrentStep = 3;
    }

    private void NextFromReferences()
    {
        ValidationErrors.Clear();

        for (int i = 0; i < References.Count; i++)
        {
            var r = References[i];
            if (string.IsNullOrWhiteSpace(r.Name))
                ValidationErrors.Add($"Reference {i + 1}: Name is required.");
            if (string.IsNullOrWhiteSpace(r.Relationship))
                ValidationErrors.Add($"Reference {i + 1}: Relationship is required.");
            if (string.IsNullOrWhiteSpace(r.Email))
                ValidationErrors.Add($"Reference {i + 1}: Email is required.");
            if (string.IsNullOrWhiteSpace(r.Phone))
                ValidationErrors.Add($"Reference {i + 1}: Phone is required.");
        }

        if (ValidationErrors.Count > 0) return;

        CompletedSteps.Add(3);
        CurrentStep = 4;
    }

    private void NextFromCoverLetter()
    {
        CompletedSteps.Add(4);
        CurrentStep = 5;
    }

    private async Task SubmitApplication()
    {
        IsSubmitting = true;

        var personal = new PersonalInfo(FullName, Email, Phone, Address);
        var workHistory = new WorkHistory(WorkEntries.Select((e, i) => new WorkEntry(
            e.Company, e.Title, e.StartDate, CurrentJobFlags[i] ? null : e.EndDate, e.Description
        )).ToList());
        var refs = References.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
        var application = new JobApplication(personal, workHistory, refs, CoverLetter);

        ApplicationId = await ApplicationService.SubmitApplicationAsync(application);
        IsSubmitting = false;
        Submitted = true;
    }

    public class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public string Description { get; set; } = "";
    }

    public class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}

@namespace sv_a81bc722eab54535b4185d6e3fc46a91.Components.Pages.Apply

<nav aria-label="Application steps" class="mb-3">
    <ol class="step-indicator d-flex list-unstyled justify-content-between p-0 m-0">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var step = i + 1;
            var isCurrent = step == CurrentStep;
            var isCompleted = CompletedSteps.Contains(step);
            var cssClass = isCurrent ? "step active" : isCompleted ? "step completed" : "step dimmed";

            <li class="@cssClass text-center flex-fill"
                style="cursor: @(isCompleted ? "pointer" : "default")"
                @onclick="() => StepClicked(step)">

                <div class="step-circle mx-auto mb-1
                    @(isCurrent ? "bg-primary text-white" : isCompleted ? "bg-success text-white" : "bg-light text-muted")">
                    @if (isCompleted)
                    {
                        <span>✓</span>
                    }
                    else
                    {
                        <span>@step</span>
                    }
                </div>
                <small class="@(isCurrent ? "fw-bold" : isCompleted ? "" : "text-muted")">@StepNames[i]</small>
            </li>
        }
    </ol>
</nav>

<style>
    .step-circle {
        width: 36px;
        height: 36px;
        border-radius: 50%;
        display: flex;
        align-items: center;
        justify-content: center;
        font-weight: bold;
        border: 2px solid transparent;
    }
    .step.active .step-circle {
        border-color: var(--bs-primary);
    }
    .step.completed .step-circle {
        border-color: var(--bs-success);
    }
    .step.dimmed .step-circle {
        border-color: #dee2e6;
    }
</style>

@code {
    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }

    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    private async Task StepClicked(int step)
    {
        if (CompletedSteps.Contains(step))
        {
            await OnStepClicked.InvokeAsync(step);
        }
    }
}

@namespace sv_a81bc722eab54535b4185d6e3fc46a91.Components.Pages.Apply

<h4>Personal Information</h4>

@if (ValidationErrors.Count > 0)
{
    <div class="alert alert-danger">
        <ul class="mb-0">
            @foreach (var error in ValidationErrors)
            {
                <li>@error</li>
            }
        </ul>
    </div>
}

<div class="mb-3">
    <label class="form-label">Full Name <span class="text-danger">*</span></label>
    <input type="text" class="form-control" value="@FullName"
           @oninput="e => FullNameChanged.InvokeAsync(e.Value?.ToString() ?? "")" />
</div>

<div class="mb-3">
    <label class="form-label">Email <span class="text-danger">*</span></label>
    <input type="email" class="form-control @(EmailError != null ? "is-invalid" : "")" value="@Email"
           @oninput="e => EmailChanged.InvokeAsync(e.Value?.ToString() ?? "")" />
    @if (EmailError != null)
    {
        <div class="invalid-feedback">@EmailError</div>
    }
</div>

<div class="mb-3">
    <label class="form-label">Phone <span class="text-danger">*</span></label>
    <input type="tel" class="form-control" value="@Phone"
           @oninput="e => PhoneChanged.InvokeAsync(e.Value?.ToString() ?? "")" />
</div>

<div class="mb-3">
    <label class="form-label">Address <span class="text-danger">*</span></label>
    <textarea class="form-control" rows="2" @oninput="e => AddressChanged.InvokeAsync(e.Value?.ToString() ?? "")">@Address</textarea>
</div>

<div class="d-flex justify-content-end">
    <button class="btn btn-primary" @onclick="OnNext">Next →</button>
</div>

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";
    [Parameter] public EventCallback<string> FullNameChanged { get; set; }
    [Parameter] public EventCallback<string> EmailChanged { get; set; }
    [Parameter] public EventCallback<string> PhoneChanged { get; set; }
    [Parameter] public EventCallback<string> AddressChanged { get; set; }
    [Parameter] public string? EmailError { get; set; }
    [Parameter] public List<string> ValidationErrors { get; set; } = new();
    [Parameter] public EventCallback OnNext { get; set; }
}

@namespace sv_a81bc722eab54535b4185d6e3fc46a91.Components.Pages.Apply
@using static Apply

<h4>Work History</h4>

@if (ValidationErrors.Count > 0)
{
    <div class="alert alert-danger">
        <ul class="mb-0">
            @foreach (var error in ValidationErrors)
            {
                <li>@error</li>
            }
        </ul>
    </div>
}

@for (int idx = 0; idx < WorkEntries.Count; idx++)
{
    var i = idx;
    var entry = WorkEntries[i];

    <div class="card mb-3">
        <div class="card-body">
            <div class="d-flex justify-content-between align-items-center mb-2">
                <h5 class="mb-0">Position @(i + 1)</h5>
                @if (WorkEntries.Count > 1)
                {
                    <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveEntry(i)">Remove</button>
                }
            </div>

            <div class="row">
                <div class="col-md-6 mb-3">
                    <label class="form-label">Company Name <span class="text-danger">*</span></label>
                    <input type="text" class="form-control" value="@entry.Company"
                           @oninput="e => entry.Company = e.Value?.ToString() ?? """/>
                </div>
                <div class="col-md-6 mb-3">
                    <label class="form-label">Job Title <span class="text-danger">*</span></label>
                    <input type="text" class="form-control" value="@entry.Title"
                           @oninput="e => entry.Title = e.Value?.ToString() ?? """/>
                </div>
            </div>

            <div class="row">
                <div class="col-md-4 mb-3">
                    <label class="form-label">Start Date <span class="text-danger">*</span></label>
                    <input type="date" class="form-control" value="@(entry.StartDate == default ? "" : entry.StartDate.ToString("yyyy-MM-dd"))"
                           @onchange="e => entry.StartDate = DateTime.TryParse(e.Value?.ToString(), out var d) ? d : default"/>
                </div>
                <div class="col-md-4 mb-3">
                    <label class="form-label">End Date</label>
                    <input type="date" class="form-control" disabled="@CurrentFlags[i]"
                           value="@(entry.EndDate?.ToString("yyyy-MM-dd") ?? "")"
                           @onchange="e => entry.EndDate = DateTime.TryParse(e.Value?.ToString(), out var d) ? d : null"/>
                </div>
                <div class="col-md-4 mb-3 d-flex align-items-end">
                    <div class="form-check">
                        <input type="checkbox" class="form-check-input" id="current-@i" checked="@CurrentFlags[i]"
                               @onchange="e => ToggleCurrent(i, (bool)(e.Value ?? false))"/>
                        <label class="form-check-label" for="current-@i">Currently working here</label>
                    </div>
                </div>
            </div>

            <div class="mb-2">
                <label class="form-label">Description</label>
                <textarea class="form-control" rows="3" @oninput="e => entry.Description = e.Value?.ToString() ?? """>@entry.Description</textarea>
            </div>
        </div>
    </div>
}

<button class="btn btn-outline-secondary mb-3" @onclick="AddEntry">+ Add Another Position</button>

<div class="d-flex justify-content-between">
    <button class="btn btn-secondary" @onclick="OnBack">← Back</button>
    <button class="btn btn-primary" @onclick="OnNext">Next →</button>
</div>

@code {
    [Parameter] public List<WorkEntryModel> WorkEntries { get; set; } = new();
    [Parameter] public List<bool> CurrentFlags { get; set; } = new();
    [Parameter] public List<string> ValidationErrors { get; set; } = new();
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }

    private void AddEntry()
    {
        WorkEntries.Add(new WorkEntryModel());
        CurrentFlags.Add(false);
    }

    private void RemoveEntry(int index)
    {
        WorkEntries.RemoveAt(index);
        CurrentFlags.RemoveAt(index);
    }

    private void ToggleCurrent(int index, bool value)
    {
        CurrentFlags[index] = value;
        if (value)
            WorkEntries[index].EndDate = null;
    }
}

@namespace sv_a81bc722eab54535b4185d6e3fc46a91.Components.Pages.Apply
@using static Apply

<h4>References</h4>

@if (ValidationErrors.Count > 0)
{
    <div class="alert alert-danger">
