{"file_text": "@namespace sv_a81bc722eab54535b4185d6e3fc46a91.Components.Pages.Apply

<nav aria-label="Application steps" class="mb-3">
    <ol class="step-indicator d-flex list-unstyled justify-content-between p-0 m-0">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var step = i + 1;
            var isCurrent = step == CurrentStep;
            var isCompleted = CompletedSteps.Contains(step);
            var cssClass = isCurrent ? "step active" : isCompleted ? "step completed" : "step dimmed";

            <li class="@cssClass text-center flex-fill"
                style="cursor: @(isCompleted ? "pointer" : "default")"
                @onclick="() => StepClicked(step)">

                <div class="step-circle mx-auto mb-1
                    @(isCurrent ? "bg-primary text-white" : isCompleted ? "bg-success text-white" : "bg-light text-muted")">
                    @if (isCompleted)
                    {
                        <span>✓</span>
                    }
                    else
                    {
                        <span>@step</span>
                    }
                </div>
                <small class="@(isCurrent ? "fw-bold" : isCompleted ? "" : "text-muted")">@StepNames[i]</small>
            </li>
        }
    </ol>
</nav>

<style>
    .step-circle {
        width: 36px;
        height: 36px;
        border-radius: 50%;
        display: flex;
        align-items: center;
        justify-content: center;
        font-weight: bold;
        border: 2px solid transparent;
    }
    .step.active .step-circle {
        border-color: var(--bs-primary);
    }
    .step.completed .step-circle {
        border-color: var(--bs-success);
    }
    .step.dimmed .step-circle {
        border-color: #dee2e6;
    }
</style>

@code {
    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }

    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    private async Task StepClicked(int step)
    {
        if (CompletedSteps.Contains(step))
        {
            await OnStepClicked.InvokeAsync(step);
        }
    }
}
