@page "/apply"
@rendermode InteractiveServer
@using sv_a81bc722eab54535b4185d6e3fc46a91.Models
@using sv_a81bc722eab54535b4185d6e3fc46a91.Services
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<h1 class="mb-4">Job Application</h1>

@if (Submitted)
{
    <div class="alert alert-success text-center py-5">
        <h2>🎉 Application Submitted!</h2>
        <p class="lead mt-3">Your application has been received.</p>
        <p>Application ID: <strong>@ApplicationId</strong></p>
    </div>
}
else
{
    <StepIndicator CurrentStep="CurrentStep"
                   CompletedSteps="CompletedSteps"
                   OnStepClicked="GoToStep" />

    <div class="card mt-4">
        <div class="card-body">
            @if (CurrentStep == 1)
            {
                <StepPersonalInfo FullName="@FullName"
                                  Email="@Email"
                                  Phone="@Phone"
                                  Address="@Address"
                                  FullNameChanged="v => FullName = v"
                                  EmailChanged="v => Email = v"
                                  PhoneChanged="v => Phone = v"
                                  AddressChanged="v => Address = v"
                                  EmailError="@EmailError"
                                  ValidationErrors="@ValidationErrors"
                                  OnNext="NextFromPersonalInfo" />
            }
            else if (CurrentStep == 2)
            {
                <StepWorkHistory WorkEntries="WorkEntries"
                                 CurrentFlags="CurrentJobFlags"
                                 ValidationErrors="@ValidationErrors"
                                 OnBack="Back"
                                 OnNext="NextFromWorkHistory" />
            }
            else if (CurrentStep == 3)
            {
                <StepReferences References="References"
                                ValidationErrors="@ValidationErrors"
                                OnBack="Back"
                                OnNext="NextFromReferences" />
            }
            else if (CurrentStep == 4)
            {
                <StepCoverLetter CoverLetter="@CoverLetter"
                                 CoverLetterChanged="v => CoverLetter = v"
                                 OnBack="Back"
                                 OnNext="NextFromCoverLetter" />
            }
            else if (CurrentStep == 5)
            {
                <StepReview FullName="@FullName"
                            Email="@Email"
                            Phone="@Phone"
                            Address="@Address"
                            WorkEntries="WorkEntries"
                            CurrentFlags="CurrentJobFlags"
                            References="References"
                            CoverLetter="@CoverLetter"
                            IsSubmitting="IsSubmitting"
                            OnEdit="GoToStep"
                            OnSubmit="SubmitApplication" />
            }
        </div>
    </div>
}

@code {
    private int CurrentStep { get; set; } = 1;
    private HashSet<int> CompletedSteps { get; set; } = new();
    private List<string> ValidationErrors { get; set; } = new();
    private string? EmailError { get; set; }
    private bool IsSubmitting { get; set; }
    private bool Submitted { get; set; }
    private int ApplicationId { get; set; }

    // Step 1
    private string FullName { get; set; } = "";
    private string Email { get; set; } = "";
    private string Phone { get; set; } = "";
    private string Address { get; set; } = "";

    // Step 2
    private List<WorkEntryModel> WorkEntries { get; set; } = new() { new WorkEntryModel() };
    private List<bool> CurrentJobFlags { get; set; } = new() { false };

    // Step 3
    private List<ReferenceModel> References { get; set; } = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4
    private string CoverLetter { get; set; } = "";

    private void GoToStep(int step)
    {
        if (CompletedSteps.Contains(step) || step == CurrentStep)
        {
            ValidationErrors.Clear();
            EmailError = null;
            CurrentStep = step;
        }
    }

    private void Back()
    {
        ValidationErrors.Clear();
        EmailError = null;
        CurrentStep--;
    }

    private async Task NextFromPersonalInfo()
    {
        ValidationErrors.Clear();
        EmailError = null;

        if (string.IsNullOrWhiteSpace(FullName))
            ValidationErrors.Add("Full name is required.");
        if (string.IsNullOrWhiteSpace(Email))
            ValidationErrors.Add("Email is required.");
        if (string.IsNullOrWhiteSpace(Phone))
            ValidationErrors.Add("Phone is required.");
        if (string.IsNullOrWhiteSpace(Address))
            ValidationErrors.Add("Address is required.");

        if (ValidationErrors.Count > 0) return;

        var emailValid = await ApplicationService.ValidateEmailAsync(Email);
        if (!emailValid)
        {
            EmailError = "Please enter a valid email address.";
            return;
        }

        CompletedSteps.Add(1);
        CurrentStep = 2;
    }

    private void NextFromWorkHistory()
    {
        ValidationErrors.Clear();

        for (int i = 0; i < WorkEntries.Count; i++)
        {
            var e = WorkEntries[i];
            if (string.IsNullOrWhiteSpace(e.Company))
                ValidationErrors.Add($"Entry {i + 1}: Company name is required.");
            if (string.IsNullOrWhiteSpace(e.Title))
                ValidationErrors.Add($"Entry {i + 1}: Job title is required.");
            if (e.StartDate == default)
                ValidationErrors.Add($"Entry {i + 1}: Start date is required.");
        }

        if (ValidationErrors.Count > 0) return;

        CompletedSteps.Add(2);
        CurrentStep = 3;
    }

    private void NextFromReferences()
    {
        ValidationErrors.Clear();

        for (int i = 0; i < References.Count; i++)
        {
            var r = References[i];
            if (string.IsNullOrWhiteSpace(r.Name))
                ValidationErrors.Add($"Reference {i + 1}: Name is required.");
            if (string.IsNullOrWhiteSpace(r.Relationship))
                ValidationErrors.Add($"Reference {i + 1}: Relationship is required.");
            if (string.IsNullOrWhiteSpace(r.Email))
                ValidationErrors.Add($"Reference {i + 1}: Email is required.");
            if (string.IsNullOrWhiteSpace(r.Phone))
                ValidationErrors.Add($"Reference {i + 1}: Phone is required.");
        }

        if (ValidationErrors.Count > 0) return;

        CompletedSteps.Add(3);
        CurrentStep = 4;
    }

    private void NextFromCoverLetter()
    {
        CompletedSteps.Add(4);
        CurrentStep = 5;
    }

    private async Task SubmitApplication()
    {
        IsSubmitting = true;

        var personal = new PersonalInfo(FullName, Email, Phone, Address);
        var workHistory = new WorkHistory(WorkEntries.Select((e, i) => new WorkEntry(
            e.Company, e.Title, e.StartDate, CurrentJobFlags[i] ? null : e.EndDate, e.Description
        )).ToList());
        var refs = References.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
        var application = new JobApplication(personal, workHistory, refs, CoverLetter);

        ApplicationId = await ApplicationService.SubmitApplicationAsync(application);
        IsSubmitting = false;
        Submitted = true;
    }

    public class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public string Description { get; set; } = "";
    }

    public class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}

